def frame(w, h, t, c, y=0.0, z=0.0, d=0.08): return [bx(-(w - t)/2, y, z, t, h, d, c), bx((w - t)/2, y, z, t, h, d, c), bx(0, y, z, w, t, d, c), bx(0, y + h - t, z, w, t, d, c)]
