# ---------------------------------------------------------------- floor patches (2 x 2 m, y = 0.02)
def floor(n, base, cells, note, use='floor'):
    g = [bx(0, 0.0, 0, 2.0, 0.02, 2.0, base)]
    for i in range(cells[0]):
        for j in range(cells[1]):
            c = cells[2](i, j)
            if c: g.append(bx(-1.0 + (i + 0.5)*2.0/cells[0], 0.02, -1.0 + (j + 0.5)*2.0/cells[1], 2.0/cells[0] - 0.02, 0.005, 2.0/cells[1] - 0.02, c))
    R(n, g, note, use=use)
floor('floor_checker', 'tileW', (6, 6, lambda i, j: 'tileK' if (i + j) % 2 else None), '2 m of black and white checker tile: diners, ice cream shops, barbers, bars')
floor('floor_checker_red', 'tileW', (6, 6, lambda i, j: 'tileR' if (i + j) % 2 else None), '2 m of red and white checker tile: pizza places and old diners')
floor('floor_linoleum', 'lino', (4, 4, lambda i, j: 'linoD' if (i * 3 + j) % 5 == 0 else None), '2 m of tan linoleum: school halls, clinics, kitchens, offices')
floor('floor_carpet_grey', 'carpetG', (1, 1, lambda i, j: None), '2 m of grey office carpet: offices, banks, libraries, agencies')
floor('floor_carpet_blue', 'carpetB', (1, 1, lambda i, j: None), '2 m of navy carpet: banks, law, funeral, hotel halls')
floor('floor_carpet_red', 'carpetR', (6, 1, lambda i, j: 'carpetT' if i in (0, 5) else None), '2 m of red carpet with a tan border: cinemas, theatres, churches, hotel lobbies')
floor('floor_carpet_patterned', 'carpetT', (4, 4, lambda i, j: 'carpetR' if (i + j) % 2 == 0 and i % 2 == 0 else None), '2 m of patterned motel carpet')
floor('floor_hardwood', 'hard', (1, 6, lambda i, j: 'hardD' if j % 2 else None), '2 m of hardwood boards: bars, boutiques, studios, restaurants, courts')
